scores = {"alice": 90, "bob": 85}

def silent_lookup(name):
    try:
        return scores[name]
    except KeyError:
        pass

def reported_lookup(name):
    try:
        return scores[name]
    except KeyError:
        print(f"No score found for {name}.")
        return None

print(silent_lookup("carol"))
print(reported_lookup("carol"))

