def count_valid_ages(entries):
    count = 0
    for entry in entries:
        try:
            int(entry)
        except ValueError:
            print(f"Skipping invalid age: {entry}")
        else:
            count += 1
    return count

print(count_valid_ages(["25", "thirty", "41", ""]))
